using System.IO.Compression;
using System.Text;

namespace WinPool.Infrastructure.Windows;

internal static class EmbeddedStorageInventoryScript
{
    // GZip-compressed UTF-8 source. Keeping the fixed command in the assembly
    // prevents a writable deployment-side script from becoming an execution input.
    private const string CompressedBase64 =
        "";

    public static string Source => ForPurpose(WinPool.Application.CollectionPurpose.Hardware);

    public static string ForPurpose(WinPool.Application.CollectionPurpose purpose)
    {
            var compressed = Convert.FromBase64String(CompressedBase64);
            using var input = new MemoryStream(compressed);
            using var gzip = new GZipStream(input, CompressionMode.Decompress);
            using var reader = new StreamReader(gzip, Encoding.UTF8);
            return "$WinPoolIncludeHardware = " + (purpose == WinPool.Application.CollectionPurpose.Hardware ? "$true" : "$false") + "\n" + reader.ReadToEnd();
    }
}
